import os, json
api_key = open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
from bioblend.galaxy import GalaxyInstance
gi = GalaxyInstance('https://usegalaxy.org', api_key)

history_id = 'bbd44e69cb8906b5c0540926abb0523b'
tool_id = 'toolshed.g2.bx.psu.edu/repos/iuc/deseq2/deseq2/2.11.40.8+galaxy3'

# Get full tool details
try:
    result = gi.tools.show_tool(tool_id)
    # Print the inputs structure
    inputs = result.get('inputs', [])
    print(f"Number of top-level inputs: {len(inputs)}")
    for inp in inputs:
        print(f"\nInput: name={inp.get('name')}, type={inp.get('type')}, label={inp.get('label')}")
        if inp.get('type') == 'repeat':
            print(f"  Repeat name: {inp.get('name')}")
            for sub in inp.get('inputs', []):
                print(f"    Sub: name={sub.get('name')}, type={sub.get('type')}")
                if sub.get('type') == 'section':
                    for sub2 in sub.get('inputs', []):
                        print(f"      Field: name={sub2.get('name')}, type={sub2.get('type')}, optional={sub2.get('optional')}")
        elif inp.get('type') == 'conditional':
            print(f"  Conditional: test_param={inp.get('test_param')}")
            cases = inp.get('cases', [])
            for case in cases:
                print(f"    Case: value={case.get('value')}")
                for sub in case.get('inputs', []):
                    print(f"      Field: name={sub.get('name')}, type={sub.get('type')}")
except Exception as e:
    print(f"Error: {e}")
