import os, json
api_key = open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
from bioblend.galaxy import GalaxyInstance
gi = GalaxyInstance('https://usegalaxy.org', api_key)

history_id = 'bbd44e69cb8906b5c0540926abb0523b'

# Test if the API works at all - try a simple tool
try:
    result = gi.tools.run_tool(
        history_id=history_id,
        tool_id='cat1',  # Concatenate tool
        tool_inputs={
            'input1': {'src': 'hda', 'id': 'f9cad7b01a47213551e6f933fe6a178e'},
            'queries_0|input2': {'src': 'hda', 'id': 'f9cad7b01a472135174d836b20adf3d0'}
        },
        input_format='legacy'
    )
    print("Simple tool worked!")
    print(json.dumps(result, indent=2)[:1000])
except Exception as e:
    print(f"Simple tool also failed: {type(e).__name__}: {str(e)[:300]}")

# Try the paste tool (head-to-head)
try:
    result = gi.tools.run_tool(
        history_id=history_id,
        tool_id='Paste1',  
        tool_inputs={
            'input1': {'src': 'hda', 'id': 'f9cad7b01a47213551e6f933fe6a178e'},
            'input2': {'src': 'hda', 'id': 'f9cad7b01a472135174d836b20adf3d0'}
        },
        input_format='legacy'
    )
    print("Paste tool worked!")
    print(json.dumps(result, indent=2)[:1000])
except Exception as e:
    print(f"Paste tool error: {type(e).__name__}: {str(e)[:300]}")
